import React, { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem('user') || 'null');

  const logout = () => {
    localStorage.removeItem('userToken');
    localStorage.removeItem('user');
    navigate('/');
    window.location.reload();
  };

  const links = [
    { to: '/', label: 'Home', end: true },
    { to: '/clients', label: 'Clients' },
    { to: '/news', label: 'News' },
    { to: '/about', label: 'About' },
    { to: '/contact', label: 'Contact' },
  ];

  return (
    <nav style={s.nav}>
      <div style={s.inner}>
        <NavLink to="/" style={s.logo}>
          All <span style={{ color: '#f97316' }}>Things</span>
        </NavLink>

        <div style={s.links}>
          {links.map(({ to, label, end }) => (
            <NavLink key={to} to={to} end={end}
              style={({ isActive }) => ({ ...s.link, ...(isActive ? s.active : {}) })}>
              {label}
            </NavLink>
          ))}
          {user ? (
            <>
              <NavLink to="/dashboard" style={({ isActive }) => ({ ...s.link, ...(isActive ? s.active : {}) })}>
                👤 {user.full_name?.split(' ')[0]}
              </NavLink>
              <button onClick={logout} style={{ ...s.link, background: 'none', border: 'none', cursor: 'pointer', color: '#ef4444' }}>
                Sign Out
              </button>
            </>
          ) : (
            <>
              <NavLink to="/login" style={({ isActive }) => ({ ...s.link, ...(isActive ? s.active : {}) })}>Sign In</NavLink>
              <NavLink to="/register" style={s.cta}>Register</NavLink>
            </>
          )}
        </div>

        <button style={s.burger} onClick={() => setOpen(!open)}>☰</button>
      </div>

      {open && (
        <div style={s.mobile}>
          {links.map(({ to, label, end }) => (
            <NavLink key={to} to={to} end={end} onClick={() => setOpen(false)}
              style={({ isActive }) => ({ ...s.mobileLink, ...(isActive ? { color: '#f97316' } : {}) })}>
              {label}
            </NavLink>
          ))}
          {user
            ? <NavLink to="/dashboard" onClick={() => setOpen(false)} style={s.mobileLink}>👤 My Dashboard</NavLink>
            : <>
                <NavLink to="/login" onClick={() => setOpen(false)} style={s.mobileLink}>Sign In</NavLink>
                <NavLink to="/register" onClick={() => setOpen(false)} style={{ ...s.mobileLink, color: '#f97316' }}>Register</NavLink>
              </>
          }
        </div>
      )}
    </nav>
  );
}

const s = {
  nav: { background: 'rgba(10,10,10,0.95)', backdropFilter: 'blur(10px)', borderBottom: '1px solid #1a1a1a', position: 'sticky', top: 0, zIndex: 100 },
  inner: { maxWidth: 1200, margin: '0 auto', padding: '0 24px', height: 64, display: 'flex', alignItems: 'center', justifyContent: 'space-between' },
  logo: { fontSize: 20, fontWeight: 800, color: '#fff' },
  links: { display: 'flex', alignItems: 'center', gap: 8 },
  link: { padding: '8px 14px', color: '#a3a3a3', fontSize: 14, borderRadius: 8, transition: 'color 0.2s' },
  active: { color: '#f97316' },
  cta: { marginLeft: 8, padding: '9px 20px', background: '#f97316', color: '#000', borderRadius: 8, fontWeight: 700, fontSize: 14 },
  burger: { display: 'none', background: 'none', border: 'none', color: '#fff', fontSize: 22 },
  mobile: { padding: '12px 24px 20px', display: 'flex', flexDirection: 'column', gap: 4 },
  mobileLink: { padding: '10px 0', color: '#a3a3a3', fontSize: 15, borderBottom: '1px solid #1a1a1a' },
};
